  pt: { title: "Referência do treino de reflexo com múltiplos alvos", headers: ["Etapa", "Reação média", "Meta de precisão", "Foco"], rows: [["Início", ">330 ms", "<72%", "Aprender ordem e cliques seguros"], ["Evolução", "270–330 ms", "72–82%", "Buscar a rajada inteira"], ["Consistente", "220–269 ms", "83–91%", "Priorizar expiração sem pressa"], ["Avançado", "180–219 ms", "92–97%", "Eliminar rajadas densas com controle"], ["Apenas referência", "<180 ms", "98%+", "Comparar o mesmo equipamento"]], note: "Faixas editoriais de prática apenas para este treino. Não são normas clínicas, percentis populacionais ou garantia de rank." },
  es: { title: "Referencia del entrenamiento con varios objetivos", headers: ["Etapa", "Reacción media", "Objetivo de precisión", "Enfoque"], rows: [["Inicio", ">330 ms", "<72%", "Aprender orden y clics seguros"], ["Progreso", "270–330 ms", "72–82%", "Buscar toda la ráfaga"], ["Constante", "220–269 ms", "83–91%", "Priorizar caducidad sin precipitarse"], ["Avanzado", "180–219 ms", "92–97%", "Limpiar ráfagas densas con control"], ["Solo referencia", "<180 ms", "98%+", "Comparar el mismo equipo"]], note: "Rangos editoriales de práctica para este ejercicio. No son normas clínicas, percentiles de población ni garantía de rango." },
  fr: { title: "Repère du test de réflexes à cibles multiples", headers: ["Niveau", "Réaction moyenne", "Objectif de précision", "Priorité"], rows: [["Départ", ">330 ms", "<72 %", "Apprendre ordre et clics sûrs"], ["Progression", "270–330 ms", "72–82 %", "Explorer toute la rafale"], ["Régulier", "220–269 ms", "83–91 %", "Prioriser la disparition sans précipiter"], ["Avancé", "180–219 ms", "92–97 %", "Nettoyer les rafales denses avec contrôle"], ["Référence seulement", "<180 ms", "98 %+", "Comparer le même matériel"]], note: "Repères éditoriaux d'entraînement pour cet exercice. Ni normes cliniques, ni percentiles de population, ni garantie de classement." }
